/* ── New: bridge mock (HKL side simulation) ──────────────────────────── */

const BRIDGE = {
  /* HKL → Composer: held-keys broadcast. Composer's bridge.on handler
   * should store these in lastHeldKeys so subsequent keystrokes consume
   * them. We verify reception by checking getHeldKeys(). */
  bridgeHeldKeysReceived: {
    setup: `
      const notes = [{ q: 0, r: 0, pname: 'a', accid: '', oct: 3, midi: 57, colorHex: '#888', velocity: 80 }];
      window.__bridgeMock.sendHeldKeys(notes);
    `,
  },

  /* Composer → HKL: capture a manually-emitted bridge event. (The
   * page's startup handshake fires before the test mock is attached,
   * so we explicitly emit from inside the page to verify the mock's
   * capture path works.) */
  bridgeComposerToHklCapture: {
    setup: `
      window.__bridgeMock.reset();
      window.__hkl_composer.bridge.send({ type: 'request-state' });
    `,
  },

  /* Composer → HKL: the "Composer view in HKL" streams. On connect (hkl-hello)
   * Composer broadcasts composer-score (the cursor instrument's MEI) and
   * composer-cursor (the editing cursor's measure). Asserted via
   * FIXTURE_ASSERTIONS.composerViewBroadcasts. */
  composerViewBroadcasts: {
    setup: `
      window.__bridgeMock.reset();
      window.__bridgeMock.sendHklHello();
      m.setCursor(0, 1);
      m.insertChordAtCursor({
        notes: [{ q: 0, r: 0, pname: 'a', accid: '', oct: 3, midi: 57, colorHex: '#888', lightColorHex: '#ffcc66', velocity: 80 }],
        duration: '4', dots: 0,
      });
    `,
  },

  /* Bare Space → startPlayback → play-score event captured on bridge.
   * sendHklHello flips hklConnected=true so playback isn't gated by the
   * "Open HKL in another tab" check. Insert one note so buildPlayback has
   * an event to emit (empty score → no play-score sent). */
  space_starts_playback: {
    setup: `
      window.__bridgeMock.sendHklHello();
      m.setCursor(0, 1);
      m.insertChordAtCursor({
        notes: [{ q: 0, r: 0, pname: 'a', accid: '', oct: 3, midi: 57, colorHex: '#888', velocity: 80 }],
        duration: '4', dots: 0,
      });
      m.setCursor(0, 1);
      window.__bridgeMock.reset();
    `,
    setupKeys: [' '],
  },

  /* Multi-instrument playback tags each event with the instrument's NAME (its
     <label>), not an opaque sample-set key. Regression guard for the Viola+Piano
     "no audio" bug: the importer/model used to emit instrumentKey="piano" (a key
     HKL can't resolve → silent). A 2-instrument score (implicit "Piano" + an
     added "Viola") must send play-score events whose instrumentName set is
     exactly {Piano, Viola} — HKL resolves those against its dropdown. */
  multiInstrument_playScoreUsesNames: {
    setup: `
      window.__bridgeMock.sendHklHello();
      m.addInstrument({ name: 'Viola', staffCount: 1 });
      m.setVoice(1); m.setCursor(0);
      m.insertChordAtCursor({
        notes: [{ q: 0, r: 0, pname: 'a', accid: '', oct: 3, midi: 57, colorHex: '#888', velocity: 80 }],
        duration: '4', dots: 0,
      });
      m.setVoice(5); m.setCursor(0);
      m.insertChordAtCursor({
        notes: [{ q: 0, r: 1, pname: 'e', accid: '', oct: 4, midi: 64, colorHex: '#888', velocity: 80 }],
        duration: '4', dots: 0,
      });
      m.setVoice(1); m.setCursor(0);
      window.__bridgeMock.reset();
    `,
    setupKeys: [' '],
  },

  /* Space twice → first start, second stop. Both bridge events captured. */
  space_stops_playback: {
    setup: `
      window.__bridgeMock.sendHklHello();
      m.setCursor(0, 1);
      m.insertChordAtCursor({
        notes: [{ q: 0, r: 0, pname: 'a', accid: '', oct: 3, midi: 57, colorHex: '#888', velocity: 80 }],
        duration: '4', dots: 0,
      });
      m.setCursor(0, 1);
      window.__bridgeMock.reset();
    `,
    setupKeys: [' ', ' '],
  },

  /* Transport mutual-exclusion. A reusable single-note single-instrument
     setup (so both clock playback and Performance mode can start), then the
     transport keys/buttons drive the state transitions asserted below. */

  /* Shift+Space then Space: Performance starts, then Space STOPS it (not
     start playback). Asserts start-performance then stop-performance, and no
     play-score (Space did not fall through to playback). */
  space_stops_performance: {
    setup: `
      window.__bridgeMock.sendHklHello();
      m.setCursor(0, 1);
      m.insertChordAtCursor({
        notes: [{ q: 0, r: 0, pname: 'a', accid: '', oct: 3, midi: 57, colorHex: '#888', velocity: 80 }],
        duration: '4', dots: 0,
      });
      m.setCursor(0, 1);
      window.__bridgeMock.reset();
    `,
    setupKeys: [{ key: ' ', shift: true }, ' '],
  },

  /* Space (start playback) then Shift+Space: Shift+Space is a no-op while a
     transport runs. Asserts play-score present, NO start-performance. */
  shift_space_noop_during_playback: {
    setup: `
      window.__bridgeMock.sendHklHello();
      m.setCursor(0, 1);
      m.insertChordAtCursor({
        notes: [{ q: 0, r: 0, pname: 'a', accid: '', oct: 3, midi: 57, colorHex: '#888', velocity: 80 }],
        duration: '4', dots: 0,
      });
      m.setCursor(0, 1);
      window.__bridgeMock.reset();
    `,
    setupKeys: [' ', { key: ' ', shift: true }],
  },

  /* Shift+Space twice: the second is a no-op (Performance already running).
     Asserts exactly one start-performance and zero stop-performance. */
  shift_space_noop_during_performance: {
    setup: `
      window.__bridgeMock.sendHklHello();
      m.setCursor(0, 1);
      m.insertChordAtCursor({
        notes: [{ q: 0, r: 0, pname: 'a', accid: '', oct: 3, midi: 57, colorHex: '#888', velocity: 80 }],
        duration: '4', dots: 0,
      });
      m.setCursor(0, 1);
      window.__bridgeMock.reset();
    `,
    setupKeys: [{ key: ' ', shift: true }, { key: ' ', shift: true }],
  },

  /* Shift+Space from idle starts Performance. Asserts start-performance. */
  shift_space_starts_performance_idle: {
    setup: `
      window.__bridgeMock.sendHklHello();
      m.setCursor(0, 1);
      m.insertChordAtCursor({
        notes: [{ q: 0, r: 0, pname: 'a', accid: '', oct: 3, midi: 57, colorHex: '#888', velocity: 80 }],
        duration: '4', dots: 0,
      });
      m.setCursor(0, 1);
      window.__bridgeMock.reset();
    `,
    setupKeys: [{ key: ' ', shift: true }],
  },

  /* Play BUTTON during Performance switches transports: stop performance AND
     start playback (the buttons differ from the keys). hkl-hello is async, so
     poll until the connection indicator flips before clicking (the transports
     bail if not connected). Asserts stop-performance then play-score. */
  play_button_switches_from_performance: {
    setup: `
      window.__bridgeMock.sendHklHello();
      m.setCursor(0, 1);
      m.insertChordAtCursor({
        notes: [{ q: 0, r: 0, pname: 'a', accid: '', oct: 3, midi: 57, colorHex: '#888', velocity: 80 }],
        duration: '4', dots: 0,
      });
      m.setCursor(0, 1);
      window.__bridgeMock.reset();
      (function whenConnected(tries) {
        const conn = document.getElementById('connStatus');
        if (conn && conn.classList.contains('connected')) {
          document.getElementById('btnPerform').click();
          document.getElementById('btnPlay').click();
        } else if (tries > 0) {
          setTimeout(() => whenConnected(tries - 1), 5);
        }
      })(60);
    `,
  },

  /* Perform BUTTON during playback switches transports: stop playback AND
     start performance. Asserts stop-playback then start-performance. */
  perform_button_switches_from_playback: {
    setup: `
      window.__bridgeMock.sendHklHello();
      m.setCursor(0, 1);
      m.insertChordAtCursor({
        notes: [{ q: 0, r: 0, pname: 'a', accid: '', oct: 3, midi: 57, colorHex: '#888', velocity: 80 }],
        duration: '4', dots: 0,
      });
      m.setCursor(0, 1);
      window.__bridgeMock.reset();
      (function whenConnected(tries) {
        const conn = document.getElementById('connStatus');
        if (conn && conn.classList.contains('connected')) {
          document.getElementById('btnPlay').click();
          document.getElementById('btnPerform').click();
        } else if (tries > 0) {
          setTimeout(() => whenConnected(tries - 1), 5);
        }
      })(60);
    `,
  },

  /* The score's Setup ref coordinates (layoutReq), not the key-sig tonic,
     drive HKL's score-ref tier. With a non-default ref set, a hello-triggered
     rebroadcast carries those exact coords as set-score-ref. */
  score_ref_broadcast_carries_setup_coords: {
    setup: `
      m.setLayoutReq({ tuningMode: '5', refQ: 0, refR: 2 });
      window.__bridgeMock.reset();
      window.__bridgeMock.sendHklHello();
    `,
  },
};

/* ── Performance mode (input-driven playback) ─────────────────────────── */

const PERFORMANCE = {
  /* Two voices: V1 = quarter A3 + quarter E4; V3 = half C4. The matcher's
   * per-voice frontiers are asserted by FIXTURE_ASSERTIONS.perfTwoVoiceFrontier,
   * which drives __performance (start + strikes) and checks independent advance,
   * a no-op on a non-matching strike, per-voice bar clearing, and finish. */
  perfTwoVoiceFrontier: {
    setup: `
      window.__bridgeMock.reset();
      m.setCursor(0, 1);
      m.insertChordAtCursor({ notes: [{ q: 0, r: 0, pname: 'a', accid: '', oct: 3, midi: 57, colorHex: '#888', lightColorHex: '#888', velocity: 80 }], duration: '4', dots: 0 });
      m.insertChordAtCursor({ notes: [{ q: 0, r: 1, pname: 'e', accid: '', oct: 4, midi: 64, colorHex: '#888', lightColorHex: '#888', velocity: 80 }], duration: '4', dots: 0 });
      m.setVoice(3);
      m.setCursor(0, 3);
      m.insertChordAtCursor({ notes: [{ q: -4, r: -2, pname: 'c', accid: '', oct: 4, midi: 60, colorHex: '#888', lightColorHex: '#888', velocity: 80 }], duration: '2', dots: 0 });
    `,
  },

  /* One voice, two quarters (A3, E4): pins the RENDERED bar geometry — the bar
   * starts before the first note and thereafter sits just past the note last
   * played (never on the next one), so its x only ever increases while the
   * score is played in order. Asserted by FIXTURE_ASSERTIONS.perfBarTrailsPlayed. */
  perfBarTrailsPlayed: {
    setup: `
      window.__bridgeMock.reset();
      m.setCursor(0, 1);
      m.insertChordAtCursor({ notes: [{ q: 0, r: 0, pname: 'a', accid: '', oct: 3, midi: 57, colorHex: '#888', lightColorHex: '#888', velocity: 80 }], duration: '4', dots: 0 });
      m.insertChordAtCursor({ notes: [{ q: 0, r: 1, pname: 'e', accid: '', oct: 4, midi: 64, colorHex: '#888', lightColorHex: '#888', velocity: 80 }], duration: '4', dots: 0 });
    `,
  },

  /* One voice, one triad chord [A3, C4, E4]: striking a single member must NOT
   * advance (wait for ALL notes); striking all three advances/finishes.
   * Asserted by FIXTURE_ASSERTIONS.perfChordWaitsForAll. */
  perfChordWaitsForAll: {
    setup: `
      window.__bridgeMock.reset();
      m.setCursor(0, 1);
      m.insertChordAtCursor({ notes: [
        { q: 0, r: 0, pname: 'a', accid: '', oct: 3, midi: 57, colorHex: '#888', lightColorHex: '#888', velocity: 80 },
        { q: -4, r: -2, pname: 'c', accid: '', oct: 4, midi: 60, colorHex: '#888', lightColorHex: '#888', velocity: 80 },
        { q: 0, r: 1, pname: 'e', accid: '', oct: 4, midi: 64, colorHex: '#888', lightColorHex: '#888', velocity: 80 },
      ], duration: '4', dots: 0 });
    `,
  },

  /* MEASURE GATE — the headline case. V1 has whole notes in m1 and m2 and
   * NOTHING in m3; V3's only note is a whole in m3, deliberately the SAME
   * pitch+color as V1's m1 note. Before the measure gate, striking V1's m1 A3
   * also advanced V3 (its frontier was open from the downbeat) and V3 drew a
   * bar over the whole intro. Asserted by FIXTURE_ASSERTIONS.perfLateVoiceDormant,
   * which also pins the ended-voice bar clearing mid-piece and the end-of-score
   * freeze. */
  perfLateVoiceDormant: {
    setup: `
      window.__bridgeMock.reset();
      m.appendMeasure();
      m.appendMeasure();
      m.setVoice(1);
      m.setCursor(m.getMeasureStartCursor(1, 0), 1);
      m.insertChordAtCursor({ notes: [{ q: 0, r: 0, pname: 'a', accid: '', oct: 3, midi: 57, colorHex: '#888', lightColorHex: '#888', velocity: 80 }], duration: '1', dots: 0 });
      m.setCursor(m.getMeasureStartCursor(1, 1), 1);
      m.insertChordAtCursor({ notes: [{ q: 0, r: 2, pname: 'b', accid: '', oct: 3, midi: 59, colorHex: '#888', lightColorHex: '#888', velocity: 80 }], duration: '1', dots: 0 });
      m.setVoice(3);
      m.setCursor(m.getMeasureStartCursor(3, 2), 3);
      m.insertChordAtCursor({ notes: [{ q: 0, r: 0, pname: 'a', accid: '', oct: 3, midi: 57, colorHex: '#888', lightColorHex: '#888', velocity: 80 }], duration: '1', dots: 0 });
    `,
  },

  /* MEASURE GATE — mid-piece gap. V1 plays m1/m2/m3; V3 plays m1, is EMPTY in
   * m2 (invisible placeholders), and resumes in m3 with the same pitch as V1's
   * m2 note. V3's bar must disappear for m2, V1's m2 strike must not advance
   * V3, and V3's bar must return only when V3 itself strikes in m3 (no entry
   * cue). Asserted by FIXTURE_ASSERTIONS.perfVoiceRestGapHidesBar. */
  perfVoiceRestGapHidesBar: {
    setup: `
      window.__bridgeMock.reset();
      m.appendMeasure();
      m.appendMeasure();
      m.setVoice(1);
      m.setCursor(m.getMeasureStartCursor(1, 0), 1);
      m.insertChordAtCursor({ notes: [{ q: 0, r: 0, pname: 'a', accid: '', oct: 3, midi: 57, colorHex: '#888', lightColorHex: '#888', velocity: 80 }], duration: '1', dots: 0 });
      m.setCursor(m.getMeasureStartCursor(1, 1), 1);
      m.insertChordAtCursor({ notes: [{ q: 0, r: 1, pname: 'e', accid: '', oct: 4, midi: 64, colorHex: '#888', lightColorHex: '#888', velocity: 80 }], duration: '1', dots: 0 });
      m.setCursor(m.getMeasureStartCursor(1, 2), 1);
      m.insertChordAtCursor({ notes: [{ q: 0, r: 2, pname: 'b', accid: '', oct: 3, midi: 59, colorHex: '#888', lightColorHex: '#888', velocity: 80 }], duration: '1', dots: 0 });
      m.setVoice(3);
      m.setCursor(m.getMeasureStartCursor(3, 0), 3);
      m.insertChordAtCursor({ notes: [{ q: -4, r: -2, pname: 'c', accid: '', oct: 4, midi: 60, colorHex: '#888', lightColorHex: '#888', velocity: 80 }], duration: '1', dots: 0 });
      m.setCursor(m.getMeasureStartCursor(3, 2), 3);
      m.insertChordAtCursor({ notes: [{ q: 0, r: 1, pname: 'e', accid: '', oct: 4, midi: 64, colorHex: '#888', lightColorHex: '#888', velocity: 80 }], duration: '1', dots: 0 });
    `,
  },

  /* MEASURE GATE — a WRITTEN rest is content, so it keeps the voice on stage.
   * V1 plays m1 and m2; V3 plays m1 and has a visible whole REST in m2. When
   * the current measure becomes m2, V3's bar must STAY parked past its m1 note
   * (unlike perfVoiceRestGapHidesBar's empty layer, which hides it) — the
   * isMeasureEmptyInVoice distinction. Asserted by
   * FIXTURE_ASSERTIONS.perfWrittenRestKeepsBar. */
  perfWrittenRestKeepsBar: {
    setup: `
      window.__bridgeMock.reset();
      m.appendMeasure();
      m.setVoice(1);
      m.setCursor(m.getMeasureStartCursor(1, 0), 1);
      m.insertChordAtCursor({ notes: [{ q: 0, r: 0, pname: 'a', accid: '', oct: 3, midi: 57, colorHex: '#888', lightColorHex: '#888', velocity: 80 }], duration: '1', dots: 0 });
      m.setCursor(m.getMeasureStartCursor(1, 1), 1);
      m.insertChordAtCursor({ notes: [{ q: 0, r: 2, pname: 'b', accid: '', oct: 3, midi: 59, colorHex: '#888', lightColorHex: '#888', velocity: 80 }], duration: '1', dots: 0 });
      m.setVoice(3);
      m.setCursor(m.getMeasureStartCursor(3, 0), 3);
      m.insertChordAtCursor({ notes: [{ q: -4, r: -2, pname: 'c', accid: '', oct: 4, midi: 60, colorHex: '#888', lightColorHex: '#888', velocity: 80 }], duration: '1', dots: 0 });
      m.setCursor(m.getMeasureStartCursor(3, 1), 3);
      m.insertRestAtCursor({ duration: '1', dots: 0 });
    `,
  },
};

