      m.setCursor(0, 1);
      m.insertChordAtCursor({ notes: [{ q: 0, r: 0, pname: 'a', accid: '', oct: 4, midi: 69, colorHex: '#888', velocity: 80 }], duration: '8', dots: 0 });
      m.insertRestAtCursor({ duration: '8', dots: 0 });
      m.setCursor(1, 1);  /* between note and rest */
      r();
