      const N = (o, midi) => ({ q: 0, r: 0, pname: 'a', accid: '', oct: o, midi, colorHex: '#888', velocity: 80 });
      m.setTitle('Sonata for Viola and Piano'); m.setSubtitle('for Viola and Piano'); m.setComposer('Max Randal, Op. 12');
      m.setCursor(0, 1);
