        const evs = ps.events || [];
        const names = [...new Set(evs.map((e) => e.instrumentName))].sort();
        const badKey = evs.some((e) => e.instrumentName === 'piano' || e.instrumentName == null);
        const ok = !badKey && names.length === 2 && names[0] === 'Piano' && names[1] === 'Viola';
        return ok
